"use client"

import { useState } from "react"

import { mediaUrl } from "@/lib/media"
import { cn } from "@/lib/utils"

// Our own outputs, side by side: one prompt at a time across the image models,
// all at 1024 x 1024 on an RTX 3090 (24 GB, Ampere), BF16, weights resident unless POLICY says otherwise.
// Times are each picked image's own pipeline call from runs.jsonl (the first image after a load is slower). Every image here
// was generated by us for this article; see the article for the harness.
// "pick" is the seed we chose out of the seeds we ran (SEEDS); "time" is the
// wall time of that image's pipeline call with the policy named in POLICY.

type Shot = { src: string; seed: number; time: number }

const PROMPTS: { id: string; label: string; text: string }[] = [
  { id: "golden", label: "golden hour", text: "A two-storey modern beach house on a wide sandy beach at golden hour. Weathered cedar shingle siding, white window trim, a wraparound wooden deck on the ground floor and a glass-railed balcony above. Dune grass bends in the wind in the foreground and a boardwalk path of grey planks leads to the deck steps. Low warm sun from the left, long soft shadows, a light haze over the ocean behind. Architectural photograph, 35mm lens, natural colour, fine detail." },
  { id: "blue", label: "blue hour", text: "A two-storey wooden beach house seen from the shoreline at blue hour, a few minutes after sunset. Deep blue sky with a thin band of orange at the horizon, every window glowing warm yellow from inside, string lights along the deck railing, wet sand mirroring the lit windows, small waves sliding up the beach. Calm and quiet, long-exposure photograph." },
  { id: "interior", label: "interior", text: "Inside the upper-floor living room of a beach house, looking out through wide open sliding glass doors to the sea. Pale oak floorboards, a low linen sofa, a woven jute rug, a ceramic vase of dried grasses on a side table, sheer white curtains lifting in the breeze. Bright midday light, a wooden deck and turquoise water with the horizon beyond. Interior design photograph, wide angle, soft shadows." },
  { id: "aerial", label: "aerial cove", text: "Aerial drone photograph looking down at a small sheltered cove: a crescent of pale sand, turquoise shallows fading to deep blue water, and one two-storey beach house with a dark roof and a wooden deck at the edge of the dunes, reached by a sandy track through green coastal scrub. Late-morning sun, crisp detail, travel photography." },
  { id: "storm", label: "storm", text: "A two-storey wooden beach house on stilts on an empty beach as a storm rolls in from the sea. Dark slate clouds, a single shaft of sunlight breaking through onto the house, wind flattening the dune grass, foam-streaked waves, wet sand, one lit window. Dramatic, moody landscape photograph, high contrast." },
]
const MODELS: { id: string; label: string; steps: number }[] = [
  { id: "klein", label: "FLUX.2 klein 4B", steps: 4 },
  { id: "zimage", label: "Z-Image-Turbo", steps: 9 },
  { id: "qwen", label: "Qwen-Image-2.1", steps: 40 },
]
const SHOTS: Record<string, Record<string, Shot>> = {
  golden: { klein: { src: "/articles/beach-house-on-a-3090/img1.jpg", seed: 11, time: 5.05 }, zimage: { src: "/articles/beach-house-on-a-3090/img6.jpg", seed: 33, time: 9.27 }, qwen: { src: "/articles/beach-house-on-a-3090/img14.jpg", seed: 11, time: 66.11 } },
  blue: { klein: { src: "/articles/beach-house-on-a-3090/img2.jpg", seed: 11, time: 2.61 }, zimage: { src: "/articles/beach-house-on-a-3090/img7.jpg", seed: 33, time: 9.14 }, qwen: { src: "/articles/beach-house-on-a-3090/img15.jpg", seed: 22, time: 62.39 } },
  interior: { klein: { src: "/articles/beach-house-on-a-3090/img3.jpg", seed: 11, time: 2.61 }, zimage: { src: "/articles/beach-house-on-a-3090/img8.jpg", seed: 11, time: 9.18 }, qwen: { src: "/articles/beach-house-on-a-3090/img16.jpg", seed: 22, time: 62.44 } },
  aerial: { klein: { src: "/articles/beach-house-on-a-3090/img4.jpg", seed: 11, time: 2.62 }, zimage: { src: "/articles/beach-house-on-a-3090/img9.jpg", seed: 33, time: 9.23 }, qwen: { src: "/articles/beach-house-on-a-3090/img17.jpg", seed: 11, time: 62.4 } },
  storm: { klein: { src: "/articles/beach-house-on-a-3090/img5.jpg", seed: 33, time: 2.64 }, zimage: { src: "/articles/beach-house-on-a-3090/img10.jpg", seed: 11, time: 9.22 }, qwen: { src: "/articles/beach-house-on-a-3090/img18.jpg", seed: 11, time: 62.4 } },
}
const SEEDS = "11, 22 and 33 for klein and Z-Image; 11 and 22 for Qwen-Image-2.1"
const POLICY = "Klein and Z-Image ran with every weight resident; Qwen-Image-2.1 ran with diffusers model offload, one stage on the card at a time, because its 30.21 GiB of BF16 weights do not fit."

export function HouseCompare() {
  const [pid, setPid] = useState(PROMPTS[0]?.id ?? "")
  const p = PROMPTS.find((x) => x.id === pid) ?? PROMPTS[0]
  if (!p) return null
  return (
    <figure className="my-8 overflow-hidden rounded-md border" aria-label="The same prompt across the image models, our outputs">
      <div className="flex flex-wrap gap-1 border-b px-4 py-3 font-mono text-xs">
        {PROMPTS.map((x) => (
          <button
            key={x.id}
            type="button"
            onClick={() => setPid(x.id)}
            aria-pressed={x.id === pid}
            className={cn("rounded border px-2 py-0.5", x.id === pid ? "bg-foreground text-background" : "hover:bg-muted")}
          >
            {x.label}
          </button>
        ))}
      </div>
      <div className="grid gap-2 p-2 sm:grid-cols-3">
        {MODELS.map((m) => {
          const s = SHOTS[p.id]?.[m.id]
          return (
            <div key={m.id} className="space-y-1">
              {s ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={mediaUrl(s.src)} alt={`${m.label}: ${p.label}, seed ${s.seed}`} loading="lazy" className="aspect-square w-full rounded object-cover" />
              ) : (
                <div className="flex aspect-square w-full items-center justify-center rounded bg-muted text-xs text-muted-foreground">not run</div>
              )}
              <p className="font-mono text-[11px] text-muted-foreground">
                {m.label} · {m.steps} steps{s ? ` · seed ${s.seed} · ${s.time.toFixed(1)} s` : ""}
              </p>
            </div>
          )
        })}
      </div>
      <figcaption className="border-t px-4 py-3 text-xs text-muted-foreground">
        <span className="text-foreground">Prompt:</span> {p.text}
        <br />
        Seeds tried per model and prompt: {SEEDS}. {POLICY}
      </figcaption>
    </figure>
  )
}
